package rpx.fixtures;

import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.security.MessageDigest;
import java.text.Normalizer;
import java.util.LinkedHashSet;
import java.util.Map;

/**
 * Golden-file writers for {@link GenCollationData}: the NFD table, the
 * contract table and the human-readable summary. Split out of
 * GenCollationData purely to keep every file under the 300-line gate -- these
 * are pure "format whatever the extractor produced" functions with no
 * dependency on the extraction/validation flow.
 */
final class CollationGoldens {

	private CollationGoldens() {
	}

	// =================================================================

	/** One `<input cp hex>\t<JRE NFD cp hex>` line per covered code point. */
	static int writeNfdGolden(String path, CollationData d) throws Exception {
		LinkedHashSet<String> ins = new LinkedHashSet<String>();
		for (int cp : d.section(2)) {
			ins.add(CollationData.hex(cp)); // every decomposable code point
		}
		int[] hangul = { 0xAC00, 0xAC01, 0xAC10, 0xAE00, 0xB098, 0xB4E4, 0xC790,
				0xD55C, 0xD7A3 };
		for (int cp : hangul) {
			ins.add(CollationData.hex(cp)); // includes U+AC01 / U+D7A3
		}
		String[] seqs = { "0041 0301 0327", "0041 0327 0301", "0061 0301 0327",
				"0061 0327 0301", "0075 0308 0304", "0075 0304 0308", "0041 030A 0301",
				"004F 0308 0304", "0065 0327 0301", "006E 0303 0327", "0055 0308 030A",
				"0069 0308 0301", "0041 0315 0300", "0061 0300 0315" };
		for (String s : seqs) {
			ins.add(s); // canonically-unordered combining sequences
		}
		String[] ascii = { "0061", "0062", "0041", "005A", "0030", "0061 0062 0063",
				"0041 0042 0043", "0041 005A", "007E", "0020" };
		for (String s : ascii) {
			ins.add(s);
		}
		int[] sup = { 0x10000, 0x1D15E, 0x1D1C0, 0x20000, 0x2F800, 0x2F801, 0x2FA1D,
				0x1F600 };
		for (int cp : sup) {
			ins.add(CollationData.hex(cp)); // supplementary, incl. U+2F800
		}
		for (int cp = 0x00C0; cp <= 0x017F; cp++) {
			ins.add(CollationData.hex(cp)); // Latin Extended-A
		}
		for (int cp = 0x0386; cp <= 0x03CE; cp += 2) {
			ins.add(CollationData.hex(cp)); // Greek
		}
		for (int cp = 0x0400; cp <= 0x045F; cp += 2) {
			ins.add(CollationData.hex(cp)); // Cyrillic
		}
		PrintWriter w = new PrintWriter(new OutputStreamWriter(
				new FileOutputStream(path), "UTF-8"));
		int n = 0;
		for (String key : ins) {
			String in = decode(key);
			String out = Normalizer.normalize(in, Normalizer.Form.NFD);
			w.println(key + "\t" + cpsOf(out));
			n++;
		}
		w.close();
		if (n < 2000) {
			throw new IllegalStateException("nfd golden only " + n + " rows");
		}
		return n;
	}

	// =================================================================

	/** `<cp0> <cp1>\t<primary hex>` per key, then `IGNORABLE <cp hex>` lines. */
	static String writeContractGolden(String path, CollationData d,
			Map<Integer, String> dump) throws Exception {
		PrintWriter w = new PrintWriter(new OutputStreamWriter(
				new FileOutputStream(path), "UTF-8"));
		int[] key = d.section(10);
		int[] ce = d.section(11);
		for (int i = 0; i < key.length; i++) {
			w.println(String.format("%04X %04X\t%04X", key[i] & 0xFFFF,
					(key[i] >>> 16) & 0xFFFF, ce[i]));
		}
		int ign = 0;
		for (int cp = 0; cp <= 0xFFFF; cp++) {
			if (CollationData.isSurrogate(cp)) {
				continue;
			}
			String c = dump.get(Integer.valueOf(cp));
			if (c != null && c.length() == 0) {
				w.println("IGNORABLE " + String.format("%04X", cp));
				ign++;
			}
		}
		w.close();
		// `ign` counts every BMP code point whose CE stream is empty, which is
		// NOT the same as "ignorable contract starter": only some are starters
		// (sec[12] == 1); the rest are empty only *after* NFD rewriting
		// (e.g. U+0340/U+0341/U+0344 decompose to U+0300/U+0301/U+0308).
		// Both numbers matter, so print both explicitly.
		int starters = 0;
		for (int v : d.section(12)) {
			starters += v;
		}
		return "keys=" + key.length + " ignorable_rows=" + ign + "(" + starters
				+ " starters + " + (ign - starters) + " via NFD)";
	}

	// =================================================================

	static void writeSummary(String path, CollationData d, String binPath,
			String summary, String ceNote, int supChecked, int nfdRows,
			String contractNote, String sha, int bytes) throws Exception {
		String[] names = { "cjk_primary", "singles", "nfd_cp", "nfd_off",
				"nfd_len", "nfd_pool", "ccc_cp", "ccc_val", "contract_starter",
				"contract_count", "contract_key", "contract_key_ce", "ignorable" };
		PrintWriter w = new PrintWriter(new OutputStreamWriter(
				new FileOutputStream(path), "UTF-8"));
		w.println("M2-12 Text-Text collation data (generated by GenCollationData.java)");
		w.println("bin.path=" + binPath);
		w.println("bin.bytes=" + bytes);
		w.println("bin.sha256=" + sha);
		w.println("bin.sec_cnt=" + CollationData.SEC_CNT);
		for (int i = 0; i < CollationData.SEC_CNT; i++) {
			w.println(String.format("sec[%d] %-16s width=%d count=%d", i,
					names[i], CollationData.WIDTH[i], d.section(i).length));
		}
		w.println("model.summary=" + summary);
		w.println("model.supplementary=checked=" + supChecked + " mismatched=0");
		w.println("model.ce=" + ceNote);
		w.println("ccc.method=" + d.cccHow);
		w.println("nfd.single_cp_decompositions=" + d.nfdSingleLen);
		w.println("nfd.golden_rows=" + nfdRows);
		w.println("contract.max_key_len=" + d.maxContractKeyLen);
		w.println("contract.golden=" + contractNote);
		w.println("reference.阿(U+963F)=" + d.section(0)[0x963F - CollationData.CJK_LO]);
		w.println("reference.一(U+4E00)=" + d.section(0)[0]);
		w.println("reference.张(U+5F20)=" + d.section(0)[0x5F20 - CollationData.CJK_LO]);
		w.close();
	}

	// =================================================================

	static String decode(String hexList) {
		StringBuilder sb = new StringBuilder();
		for (String t : hexList.split(" ")) {
			sb.appendCodePoint(Integer.parseInt(t, 16));
		}
		return sb.toString();
	}

	static String cpsOf(String s) {
		StringBuilder sb = new StringBuilder();
		int i = 0;
		while (i < s.length()) {
			int cp = s.codePointAt(i);
			i += Character.charCount(cp);
			if (sb.length() > 0) {
				sb.append(' ');
			}
			sb.append(CollationData.hex(cp));
		}
		return sb.toString();
	}

	static String sha256(byte[] b) throws Exception {
		byte[] h = MessageDigest.getInstance("SHA-256").digest(b);
		StringBuilder sb = new StringBuilder();
		for (byte x : h) {
			sb.append(String.format("%02x", x));
		}
		return sb.toString();
	}
}
